head.script:
///////// 1. 변수 및 선언 영역 /////////

// 직접 저장 여부
scwin.directYn = "N";

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 팝업 파라미터(서식코드·서식버전·직접저장여부)를 수신하고 전체/할당 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    dma_search.set("formCd", $c.data.getParameter("formCd"));
    dma_search.set("formVer", $c.data.getParameter("formVer"));

    scwin.directYn = $c.data.getParameter("directYn");
    // 전체/할당 목록 조회
    scwin.fnSearch();
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name btn_save_onclick
 * @description [저장] 버튼 클릭 — 할당된 목록(dlt_list2)의 유효 행을 수집해 직접 저장 모드(directYn === "Y")면 팝업 결과로 반환하고, 아니면 편집기 분류 저장(sbm_save)을 실행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_save_onclick(e);
 */
scwin.btn_save_onclick = function (e) {
    // 웹스퀘어가 필터링 처리된 데이타는 못찾는 문제로 저장시에 필터 해제
    dlt_list2.clearFilter();

    const list = [];
    if (scwin.directYn === "Y") {
        const params = {};
        params.refreshYn = "Y";

        for (let i=0; i < dlt_list2.getRowCount(); i++) {
            if (dlt_list2.getRowStatus(i) !== "D") {
                const params = {};
                params.editMidclssCd = dlt_list2.getCellData(i, "editMidclssCd");
                params.editMidclssNm = dlt_list2.getCellData(i, "editMidclssNm");
                params.editUpclssCd = dlt_list2.getCellData(i, "editUpclssCd");
                params.editUpclssNm = dlt_list2.getCellData(i, "editUpclssNm");

                list.push(params);
            }
        }
        params.list = list;

        $c.win.closePopup(params);
    } else {
        for (let i=0; i < dlt_list2.getRowCount(); i++) {
            if (dlt_list2.getRowStatus(i) !== "D") {
                list.push(dlt_list2.getCellData(i, "editMidclssCd"));
            }
        }
        dma_save.set("formCd", dma_search.get("formCd"));
        dma_save.set("formVer", dma_search.get("formVer"));
        dma_save.set("editClssCds", list);

        $c.sbm.execute(sbm_save, dma_save.getJSON());
    }
};

/**
 * @method
 * @name btn_right_onclick
 * @description [오른쪽으로 이동] 버튼 클릭 — 전체 목록(dlt_list1)에서 체크된 행을 할당된 목록(dlt_list2)으로 이동한다(신규 행은 삭제 취소로 복원). 체크 항목이 없으면 안내한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_right_onclick(e);
 */
scwin.btn_right_onclick = function (e) {
    let count_ = 0;
    dlt_list1.setBroadcast(false);
    dlt_list2.setBroadcast(false);
    for (let i=dlt_list1.getRowCount(); i > -1; i--) {
        if (dlt_list1.getCellData(i, "CHK") === "1") {
            if (dlt_list1.getRowStatus(i) === "C") {
                dlt_list2.undeleteRow(dlt_list1.getCellData(i, "selIndex"));
                dlt_list1.removeRow(i);
            } else {
                // 할당된 목록에 추가
                dlt_list2.insertRow(dlt_list2.getRowCount());
                dlt_list2.setCellData(dlt_list2.getRowCount()-1, "editMidclssCd", dlt_list1.getCellData(i, "editClssCd"));
                dlt_list2.setCellData(dlt_list2.getRowCount()-1, "editMidclssNm", dlt_list1.getCellData(i, "editClssNm"));
                dlt_list2.setCellData(dlt_list2.getRowCount()-1, "editUpclssCd", dlt_list1.getCellData(i, "upEditClssCd"));
                dlt_list2.setCellData(dlt_list2.getRowCount()-1, "editUpclssNm", dlt_list1.getCellData(i, "upEditClssNm"));
                dlt_list2.setCellData(dlt_list2.getRowCount()-1, "editClssFullNm", dlt_list1.getCellData(i, "editClssFullNm"));
                dlt_list2.setCellData(dlt_list2.getRowCount()-1, "selIndex", i);

                dlt_list1.setCellData(i, "CHK", "0");
                dlt_list1.deleteRow(i);
            }
            count_++;
        }
    }
    dlt_list1.setBroadcast(true, true);
    dlt_list2.setBroadcast(true, true);

    // 체크가 되어 있는 항목이 있는 여부 확인
    if (count_ < 1) {
        $c.win.alert("전체 목록에 추가 할 편집기 분류 정보를 체크해 주세요.");
    }
};

/**
 * @method
 * @name btn_left_onclick
 * @description [왼쪽으로 이동] 버튼 클릭 — 할당된 목록(dlt_list2)에서 체크된 행을 전체 목록(dlt_list1)으로 되돌린다(신규 행은 삭제 취소로 복원). 체크 항목이 없으면 안내한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_left_onclick(e);
 */
scwin.btn_left_onclick = function (e) {
    let count_ = 0;
    dlt_list1.setBroadcast(false);
    dlt_list2.setBroadcast(false);
    for (let i=dlt_list2.getRowCount(); i > -1; i--) {
        if (dlt_list2.getCellData(i, "CHK") === "1") {
            if (dlt_list2.getRowStatus(i) === "C") {
                dlt_list1.undeleteRow(dlt_list2.getCellData(i, "selIndex"));
                dlt_list2.removeRow(i);
            } else {
                dlt_list1.insertRow(dlt_list1.getRowCount());
                dlt_list1.setCellData(dlt_list1.getRowCount()-1, "editClssCd", dlt_list2.getCellData(i, "editMidclssCd"));
                dlt_list1.setCellData(dlt_list1.getRowCount()-1, "editClssNm", dlt_list2.getCellData(i, "editMidclssNm"));
                dlt_list1.setCellData(dlt_list1.getRowCount()-1, "upEditClssCd", dlt_list2.getCellData(i, "editUpclssCd"));
                dlt_list1.setCellData(dlt_list1.getRowCount()-1, "upEditClssNm", dlt_list2.getCellData(i, "editUpclssNm"));
                dlt_list1.setCellData(dlt_list1.getRowCount()-1, "editClssFullNm", dlt_list2.getCellData(i, "editClssFullNm"));
                dlt_list1.setCellData(dlt_list1.getRowCount()-1, "selIndex", i);

                dlt_list2.setCellData(i, "CHK", "0");
                dlt_list2.deleteRow(i);
            }
            count_++;
        }
    }
    dlt_list1.setBroadcast(true, true);
    dlt_list2.setBroadcast(true, true);

    // 체크가 되어 있는 항목이 있는 여부 확인
    if (count_ < 1) {
        $c.win.alert("할당된 목록에 삭제 할 편집기 분류 정보를 체크해 주세요.");
    }
};

/**
 * @method
 * @name ibx_search1_onkeyup
 * @description 전체 목록 검색어 입력 — 편집기 분류 전체명(화면출력용) 기준으로 dlt_list1 을 필터링한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_search1_onkeyup(e);
 */
scwin.ibx_search1_onkeyup = function (e) {
    $c.tms.setDataListFilter(dlt_list1, ["editClssFullNm"], ibx_search1.getValue());
};

/**
 * @method
 * @name ibx_search2_onkeyup
 * @description 할당된 목록 검색어 입력 — 편집기 분류 전체명(화면출력용) 기준으로 dlt_list2 를 필터링한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_search2_onkeyup(e);
 */
scwin.ibx_search2_onkeyup = function (e) {
    $c.tms.setDataListFilter(dlt_list2, ["editClssFullNm"], ibx_search2.getValue());
};

/**
 * @method
 * @name btn_close_onclick
 * @description [닫기] 버튼 클릭 — 팝업을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_close_onclick(e);
 */
scwin.btn_close_onclick = function (e) {
    $c.win.closePopup();
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name sbm_detail_submitdone
 * @description 전체/할당 목록 조회(sbm_detail) 완료 콜백 — 조회 성공 시 전체(masterEdits)/할당(existingEdits) 목록을 재설정하고, 실패 시 오류 메시지를 알린다.
 * @param {Object} e 서브미션 응답 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (sbm_detail ev:submitdone 바인딩으로 자동 호출)
 */
scwin.sbm_detail_submitdone = function (e) {
    // 조회 성공인 경우
    const result = e.responseJSON;
    if (result.success) {
        dlt_list1.setJSON(result.body.masterEdits);
        dlt_list2.setJSON(result.body.existingEdits);
    } else {
        $c.win.alert(result.message);
    }
};

/**
 * @method
 * @name sbm_save_submitdone
 * @description 저장(sbm_save) 완료 콜백 — 저장 성공 시 완료를 알리고 재조회 플래그(refreshYn)와 함께 팝업을 닫는다. 실패 시 오류 메시지를 알린다.
 * @param {Object} e 서브미션 응답 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (sbm_save ev:submitdone 바인딩으로 자동 호출)
 */
scwin.sbm_save_submitdone = async function (e) {
    // 저장 성공인 경우
    const result = e.responseJSON;
    if (result.success) {
        await $c.win.alert("저장되었습니다.");

        const params = {};
        params.refreshYn = "Y";

        $c.win.closePopup(params);
    } else {
        $c.win.alert(result.message);
    }
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name fnSearch
 * @description 전체/할당 목록 조회 — 검색 조건(dma_search)으로 sbm_detail 을 실행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.fnSearch();
 */
scwin.fnSearch = function () {
    $c.sbm.execute(sbm_detail, dma_search.getJSON());
};
